import 'reflect-metadata';
import { MikroORM } from '@mikro-orm/postgresql';
import config from './db/mikro-orm.config.ts';
import { TodoAction, TodoDiscipline, DisciplineHistory, Habit, HabitHistory, Todo } from './db/entities/index.ts';

\(async \(\) => {
  const orm = await MikroORM.init\({ ...config, connect: false, debug: false }\);
  const em = orm.em.fork\(\);
  const conn: any = \(em as any\).getConnection\(\);
  const log: string[] = [];
  conn.execute = async \(q: string, p: any\) => { log.push\(q + '  -- params: ' + JSON.stringify\(p\)\); return []; };
  const t = async \(l: string, fn: \(\) => Promise<any>\) => {
    log.length = 0;
    try { await fn\(\); } catch \(e: any\) { log.push\('THROW ' + e.message\); }
    console.log\('### ' + l\); log.forEach\(q => console.log\(q\)\); console.log\(\);
  };

  await t\('1 TodoActionRepository.find\({mission:{user}}, orderBy\)', \(\) =>
    em.getRepository\(TodoAction\).find\({ mission: { user: 1 } }, { orderBy: { deadline: 'ASC' } } as any\)\);

  await t\('2 TodoDiscipline.find\({mission:{user}}, populate history\)', \(\) =>
    em.getRepository\(TodoDiscipline\).find\({ mission: { user: 1 } }, { populate: ['history'] as any, orderBy: { id: 'ASC' } as any } as any\)\);

  await t\('3 findOneOrFail\({id, mission:{user}}\)', \(\) =>
    em.getRepository\(TodoDiscipline\).findOneOrFail\({ id: 5, mission: { user: 1 } } as any\)\);

  await t\('4 DisciplineHistory.find\({discipline:{mission:{user}}}\)', \(\) =>
    em.getRepository\(DisciplineHistory\).find\({ discipline: { mission: { user: 1 } } } as any\)\);

  await t\('5 Habit.find\({id, user}\) + Todo.count nested', \(\) =>
    em.getRepository\(Todo\).count\({ user: 1, type: 'Mission' } as any\)\);
}\)\(\).catch\(e => console.error\('FATAL', e.message, e.stack\)\);
